package com.euvcraft.lithmod.mc.gametest;
import static com.euvcraft.lithmod.mc.gametest.T4RuntimeFixtures.*;
import com.euvcraft.lithmod.mc.cleanroom.*;
import net.minecraft.core.*;import net.minecraft.core.registries.Registries;import net.minecraft.resources.*;import net.minecraft.gametest.framework.*;
import net.minecraft.world.level.Level;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.properties.DoubleBlockHalf;import net.minecraft.world.item.ItemStack;import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.server.level.*;import net.minecraft.server.network.CommonListenerCookie;import com.mojang.authlib.GameProfile;
import net.neoforged.bus.api.IEventBus;import net.neoforged.neoforge.event.RegisterGameTestsEvent;import net.neoforged.neoforge.registries.DeferredRegister;
import java.util.*;import java.util.function.Consumer;
public final class CleanroomSafetyGameTests {
 private static final DeferredRegister<Consumer<GameTestHelper>> FUNCTIONS=DeferredRegister.create(Registries.TEST_FUNCTION,"lithmod");
 private static final Map<String,Consumer<GameTestHelper>> CASES=new LinkedHashMap<>();
 static{add("t5_cleanroom_safety_unloaded",CleanroomSafetyGameTests::unloaded);add("t5_cleanroom_safety_formation",CleanroomSafetyGameTests::formation);add("t5_cleanroom_safety_breach",CleanroomSafetyGameTests::breach);add("t5_cleanroom_safety_two_controllers",CleanroomSafetyGameTests::two);add("t5_cleanroom_safety_door",CleanroomSafetyGameTests::door);add("t5_cleanroom_safety_filtration",CleanroomSafetyGameTests::filter);add("t5_cleanroom_safety_persistence",CleanroomSafetyGameTests::persistence);add("t5_cleanroom_safety_gown",CleanroomSafetyGameTests::gown);}
 private static void add(String id,Consumer<GameTestHelper> run){CASES.put(id,run);FUNCTIONS.register(id,()->run);}
 public static void register(IEventBus bus){FUNCTIONS.register(bus);bus.addListener((Consumer<RegisterGameTestsEvent>)event->{Holder<TestEnvironmentDefinition<?>> env=event.registerEnvironment(Identifier.parse("lithmod:cleanroom_safety"),new TestEnvironmentDefinition[0]);var data=new TestData<>(env,Level.OVERWORLD,Identifier.withDefaultNamespace("empty"),400,0,true,Rotation.NONE,false,1,1,false,0);for(var name:CASES.keySet()){var id=Identifier.fromNamespaceAndPath("lithmod",name);event.registerTest(id,new FunctionGameTestInstance(ResourceKey.<Consumer<GameTestHelper>>create(Registries.TEST_FUNCTION,id),data));}});}
 private record Room(ServerLevel level,BlockPos origin,List<BlockPos> shell,CleanroomControllerBlockEntity controller,CleanroomFilterBlockEntity filter) implements AutoCloseable{
  BlockPos wall(){return origin.offset(4,1,1);}
  public void close(){for(var p:shell){if(level.getBlockEntity(p) instanceof net.minecraft.world.Container c)c.clearContent();level.setBlock(p,Blocks.AIR.defaultBlockState(),3);}}
 }
 private static Room room(GameTestHelper h){var l=h.getLevel();var min=h.absolutePos(new BlockPos(1,1,1));var shell=new ArrayList<BlockPos>();for(var m:BlockPos.betweenClosed(min,min.offset(4,4,4))){var p=m.immutable();if(p.getX()==min.getX()||p.getX()==min.getX()+4||p.getY()==min.getY()||p.getY()==min.getY()+4||p.getZ()==min.getZ()||p.getZ()==min.getZ()+4){shell.add(p);l.setBlock(p,CleanroomBlocks.WALL.get().defaultBlockState(),3);}else l.setBlock(p,Blocks.AIR.defaultBlockState(),3);}var cp=min.offset(1,1,0);var fp=min.offset(2,1,0);l.setBlock(cp,CleanroomBlocks.CONTROLLER.get().defaultBlockState(),3);l.setBlock(fp,CleanroomBlocks.FILTER.get().defaultBlockState(),3);var c=(CleanroomControllerBlockEntity)l.getBlockEntity(cp);c.revalidate();return new Room(l,min,shell,c,(CleanroomFilterBlockEntity)l.getBlockEntity(fp));}
 private static void formation(GameTestHelper h){try(var r=room(h)){eq(h,1,r.controller.state(),"Sealed cuboid forms");eq(h,27,r.controller.bounds().volume(),"Interior excludes shell");eq(h,0,r.controller.cleanliness(),"New controller dirty");var inside=r.origin.offset(1,1,1);check(h,CleanroomRooms.sample(r.level,List.of(inside)).room()==r.controller,"Contained machine belongs to room");check(h,CleanroomRooms.sample(r.level,List.of(inside,r.origin)).room()==null,"One outside member denies room");}h.succeed();}
 private static void breach(GameTestHelper h){try(var r=room(h)){var bounds=r.controller.bounds();r.level.setBlock(r.wall(),Blocks.AIR.defaultBlockState(),3);r.controller.markTopologyDirty();r.controller.validateKnown();eq(h,2,r.controller.state(),"Missing wall breaches");check(h,r.controller.bounds().equals(bounds)&&r.wall().equals(r.controller.faultPos()),"Last footprint and exact fault retained");eq(h,500,r.controller.roomYield(),"Breach yields outside factor");r.level.setBlock(r.wall(),CleanroomBlocks.WALL.get().defaultBlockState(),3);r.controller.markTopologyDirty();r.controller.validateKnown();eq(h,1,r.controller.state(),"Repaired shell encloses again");}h.succeed();}
 private static void two(GameTestHelper h){try(var r=room(h)){r.level.setBlock(r.wall(),CleanroomBlocks.CONTROLLER.get().defaultBlockState(),3);r.controller.markTopologyDirty();r.controller.validateKnown();check(h,r.controller.state()!=1,"Two controllers cannot claim one room");}h.succeed();}
 private static void door(GameTestHelper h){try(var r=room(h)){var bottom=r.wall();var state=CleanroomBlocks.DOOR.get().defaultBlockState().setValue(DoorBlock.HALF,DoubleBlockHalf.LOWER).setValue(DoorBlock.FACING,Direction.EAST);r.level.setBlock(bottom,state,2);r.level.setBlock(bottom.above(),state.setValue(DoorBlock.HALF,DoubleBlockHalf.UPPER),2);r.controller.markTopologyDirty();r.controller.validateKnown();eq(h,1,r.controller.state(),"Closed paired door seals");eq(h,0,r.controller.doors(),"Closed door no leak");r.level.setBlock(bottom,state.setValue(DoorBlock.OPEN,true),2);r.level.setBlock(bottom.above(),state.setValue(DoorBlock.HALF,DoubleBlockHalf.UPPER).setValue(DoorBlock.OPEN,true),2);r.controller.markTopologyDirty();r.controller.validateKnown();eq(h,1,r.controller.state(),"Open intact door is leak rather than shell breach");eq(h,1,r.controller.doors(),"Only one leak per two-block door");r.level.setBlock(bottom.above(),Blocks.AIR.defaultBlockState(),2);r.controller.markTopologyDirty();r.controller.validateKnown();eq(h,2,r.controller.state(),"Missing upper half breaches");}h.succeed();}
 private static void filter(GameTestHelper h){try(var r=room(h)){var c=r.controller;var f=r.filter;c.setStoredEnergy(100000);f.setStoredEnergy(100000);f.setSlot(0,new ItemStack(CleanroomItems.MEDIUM.get()));for(int i=0;i<1000;i++){if(i%100==0){c.setStoredEnergy(100000);f.setStoredEnergy(100000);}c.serverTick();}eq(h,245800,c.cleanliness(),"50 seconds of 5000 filtration minus floor(800*27/256) leakage");eq(h,11000,f.remaining(),"Media charges only working ticks");int before=c.cleanliness();f.setStoredEnergy(0);for(int i=0;i<20;i++)c.serverTick();eq(h,before-84,c.cleanliness(),"Filter outage ordinary baseline loss");eq(h,11000,f.remaining(),"No media spent with zero FE");before=c.cleanliness();c.setStoredEnergy(0);f.setStoredEnergy(100000);for(int i=0;i<20;i++)c.serverTick();eq(h,before-30084,c.cleanliness(),"Controller outage substantially stronger");eq(h,11000,f.remaining(),"Unpowered controller stops filtration");}h.succeed();}
 private static void persistence(GameTestHelper h){try(var r=room(h)){var c=r.controller;var f=r.filter;c.setStoredEnergy(100000);f.setStoredEnergy(100000);f.setSlot(0,new ItemStack(CleanroomItems.MEDIUM.get()));for(int i=0;i<100;i++)c.serverTick();int score=c.cleanliness(),wear=f.remaining();var ct=save(r.level,c);var ft=save(r.level,f);var pos=c.getBlockPos();r.level.removeBlockEntity(pos);var replacement=new CleanroomControllerBlockEntity(pos,r.level.getBlockState(pos));r.level.setBlockEntity(replacement);load(r.level,replacement,ct);eq(h,score,replacement.cleanliness(),"Score saved exactly; no offline gain");eq(h,3,replacement.state(),"Restored footprint unknown until validated");replacement.validateKnown();eq(h,1,replacement.state(),"Restored footprint validates");check(h,replacement.bounds().equals(c.bounds()),"Bounds persist");load(r.level,f,ft);eq(h,wear,f.remaining(),"Persistent media wear");}h.succeed();}
 private static void gown(GameTestHelper h){var cookie=CommonListenerCookie.createInitial(new GameProfile(UUID.randomUUID(),"cleanroom-test"),false);var p=new ServerPlayer(h.getLevel().getServer(),h.getLevel(),cookie.gameProfile(),cookie.clientInformation());check(h,!CleanroomControllerBlockEntity.gowned(p),"No gown unprotected");p.setItemSlot(EquipmentSlot.HEAD,new ItemStack(CleanroomItems.HOOD.get()));p.setItemSlot(EquipmentSlot.CHEST,new ItemStack(CleanroomItems.SUIT.get()));p.setItemSlot(EquipmentSlot.LEGS,new ItemStack(CleanroomItems.TROUSERS.get()));check(h,!CleanroomControllerBlockEntity.gowned(p),"Partial gown unprotected");p.setItemSlot(EquipmentSlot.FEET,new ItemStack(CleanroomItems.BOOTS.get()));check(h,CleanroomControllerBlockEntity.gowned(p),"Four matching pieces protect");h.succeed();}
 private static void unloaded(GameTestHelper h){var l=h.getLevel();var p=new BlockPos(20000000,100,20000000);check(h,!l.hasChunkAt(p),"Remote test chunk initially unavailable");var bounds=new RoomBounds(p.getX(),p.getY(),p.getZ(),p.getX()+4,p.getY()+4,p.getZ()+4);var result=CleanroomTopology.validate(l,p,bounds);eq(h,3,result.state(),"Unavailable footprint is UNKNOWN rather than breach");check(h,!l.hasChunkAt(p),"Validation never loads remote chunk");h.succeed();}
 private CleanroomSafetyGameTests(){}
}
